package ir.orix.school.assessment.domain;
import java.math.BigDecimal; import java.time.Instant; import jakarta.persistence.*; import ir.orix.school.academic.domain.Course; import ir.orix.school.identity.domain.UserAccount; import ir.orix.school.organization.domain.Tenant; import ir.orix.school.shared.persistence.AuditedEntity;
@Entity @Table(name="assessment",schema="school")
public class Assessment extends AuditedEntity {
 public enum Type{EXAM,QUIZ,ASSIGNMENT} public enum Status{DRAFT,PUBLISHED,ACTIVE,CLOSED,GRADING,FINALIZED,CANCELLED}
 @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="course_id") private Course course; @Column(nullable=false,length=60) private String code; @Column(nullable=false,length=200) private String title; @Enumerated(EnumType.STRING) @Column(name="assessment_type",nullable=false,length=30) private Type type; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private Status status; @Column(name="opens_at",nullable=false) private Instant opensAt; @Column(name="closes_at",nullable=false) private Instant closesAt; @Column(name="duration_minutes",nullable=false) private int durationMinutes; @Column(name="attempts_allowed",nullable=false) private int attemptsAllowed; @Column(name="randomize_questions",nullable=false) private boolean randomizeQuestions; @Column(name="price_rial",nullable=false) private long priceRial; @Column(name="total_points",nullable=false,precision=10,scale=2) private BigDecimal totalPoints; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by") private UserAccount createdBy; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="published_by") private UserAccount publishedBy; @Column(name="published_at") private Instant publishedAt;
 protected Assessment(){} public Assessment(Tenant tenant,Course course,String code,String title,Type type,Instant opens,Instant closes,int duration,int attempts,boolean randomize,long priceRial,UserAccount actor){this.tenant=tenant;this.course=course;this.code=code.strip().toUpperCase();this.title=title.strip();this.type=type;this.opensAt=opens;this.closesAt=closes;this.durationMinutes=duration;this.attemptsAllowed=attempts;this.randomizeQuestions=randomize;this.priceRial=Math.max(0,priceRial);this.createdBy=actor;this.totalPoints=BigDecimal.ZERO;this.status=Status.DRAFT;}
 public void updateTotalPoints(BigDecimal value){requireDraft();this.totalPoints=value;} public void publish(UserAccount actor,Instant now){requireDraft();this.status=Status.PUBLISHED;this.publishedBy=actor;this.publishedAt=now;} public void requireDraft(){if(status!=Status.DRAFT)throw new IllegalStateException("Assessment is no longer editable.");}
 public Course getCourse(){return course;} public String getCode(){return code;} public String getTitle(){return title;} public Type getType(){return type;} public Status getStatus(){return status;} public Instant getOpensAt(){return opensAt;} public Instant getClosesAt(){return closesAt;} public int getDurationMinutes(){return durationMinutes;} public int getAttemptsAllowed(){return attemptsAllowed;} public boolean isRandomizeQuestions(){return randomizeQuestions;} public long getPriceRial(){return priceRial;} public BigDecimal getTotalPoints(){return totalPoints;} public UserAccount getCreatedBy(){return createdBy;} public Instant getPublishedAt(){return publishedAt;}
}
